from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Baseline 2mm kernel written in a cache-friendly loop order.
#   D := alpha * A * B * C + beta * D
@proc
def kernel_2mm_base(
    ni: size,
    nj: size,
    nk: size,
    nl: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    tmp: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
    C: DATA_TYPE[nj, nl] @ DRAM,
    D: DATA_TYPE[ni, nl] @ DRAM,
):
    # Scale D by beta: D = beta * D
    for i0 in seq(0, ni):
        for j0 in seq(0, nl):
            D[i0, j0] = beta * D[i0, j0]

    # Initialize tmp to zero.
    for i1 in seq(0, ni):
        for j1 in seq(0, nj):
            tmp[i1, j1] = 0.0

    # First matrix multiplication: tmp = alpha * A * B
    # Loop order i2-k2-j2 gives unit-stride access to B and tmp.
    for i2 in seq(0, ni):
        for k2 in seq(0, nk):
            for j2 in seq(0, nj):
                tmp[i2, j2] += alpha * A[i2, k2] * B[k2, j2]

    # Second matrix multiplication: D += tmp * C
    # Loop order i3-k3-j3 gives unit-stride access to C and D.
    for i3 in seq(0, ni):
        for k3 in seq(0, nj):
            for j3 in seq(0, nl):
                D[i3, j3] += tmp[i3, k3] * C[k3, j3]


# Start from the baseline kernel.
kernel_2mm = kernel_2mm_base

# Tunable tile sizes (can be adjusted for the target cache hierarchy).
TI = 32  # tile size in the i (row) dimension
TJ = 32  # tile size in the j (column) dimension for A*B and k-dim for tmp*C
TK = 32  # tile size in the k dimension for A*B
TL = 32  # tile size in the j (column) dimension for tmp*C


# ---------------------------------------------------------------------------
# Optimize tmp = alpha * A * B
# ---------------------------------------------------------------------------

# Original nest in this phase:
#   for i2 in 0..ni:
#     for k2 in 0..nk:
#       for j2 in 0..nj:
#         tmp[i2, j2] += alpha * A[i2, k2] * B[k2, j2]

# Tile i2, j2, and k2 loops.
kernel_2mm = divide_loop(kernel_2mm, "i2", TI, ["i2_o", "i2_i"])
kernel_2mm = divide_loop(kernel_2mm, "j2", TJ, ["j2_o", "j2_i"])
kernel_2mm = divide_loop(kernel_2mm, "k2", TK, ["k2_o", "k2_i"])

# After tiling the natural order is:
#   i2_o, i2_i, k2_o, k2_i, j2_o, j2_i
# Reorder to get a tile-oriented nest:
#   for i2_o, j2_o, k2_o, i2_i, k2_i, j2_i
# This processes one (TI x TJ) tile of tmp at a time while
# streaming over blocks of K, improving cache locality for A, B, and tmp.
kernel_2mm = reorder_loops(kernel_2mm, "k2_i j2_o")
kernel_2mm = reorder_loops(kernel_2mm, "k2_o j2_o")
kernel_2mm = reorder_loops(kernel_2mm, "i2_i j2_o")
kernel_2mm = reorder_loops(kernel_2mm, "i2_i k2_o")

# Parallelize across outer tiles in the first GEMM (rows of A/tmp are independent).
kernel_2mm = parallelize_loop(kernel_2mm, "i2_o")


# ---------------------------------------------------------------------------
# Optimize D += tmp * C
# ---------------------------------------------------------------------------

# Original nest in this phase:
#   for i3 in 0..ni:
#     for k3 in 0..nj:
#       for j3 in 0..nl:
#         D[i3, j3] += tmp[i3, k3] * C[k3, j3]

# Tile i3, j3, and k3 loops.
kernel_2mm = divide_loop(kernel_2mm, "i3", TI, ["i3_o", "i3_i"])
kernel_2mm = divide_loop(kernel_2mm, "j3", TL, ["j3_o", "j3_i"])
kernel_2mm = divide_loop(kernel_2mm, "k3", TJ, ["k3_o", "k3_i"])

# As above, reorder to:
#   for i3_o, j3_o, k3_o, i3_i, k3_i, j3_i
# This gives good locality for C and D within each (TI x TL) tile and
# reuses rows of tmp across the k3 tiles.
kernel_2mm = reorder_loops(kernel_2mm, "k3_i j3_o")
kernel_2mm = reorder_loops(kernel_2mm, "k3_o j3_o")
kernel_2mm = reorder_loops(kernel_2mm, "i3_i j3_o")
kernel_2mm = reorder_loops(kernel_2mm, "i3_i k3_o")

# Parallelize across outer tiles in the second GEMM.
kernel_2mm = parallelize_loop(kernel_2mm, "i3_o")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(tmp,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NJ,NL,nj,nl);
  POLYBENCH_2D_ARRAY_DECL(D,DATA_TYPE,NI,NL,ni,nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_2mm (/*ctxt=*/NULL, ni, nj, nk, nl,
	      (DATA_TYPE*)&alpha, (DATA_TYPE*)&beta,
	      (DATA_TYPE*)POLYBENCH_ARRAY(tmp),
	      (DATA_TYPE*)POLYBENCH_ARRAY(A),
	      (DATA_TYPE*)POLYBENCH_ARRAY(B),
	      (DATA_TYPE*)POLYBENCH_ARRAY(C),
	      (DATA_TYPE*)POLYBENCH_ARRAY(D));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nl,  POLYBENCH_ARRAY(D)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(D);

  return 0;
}
