from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Optimized 2mm kernel:
#   tmp = alpha * A * B
#   D   = beta * D + tmp * C
#
# The object code is written to:
#   * Access B and C with unit-stride in the innermost loop (good cache/SIMD use).
#   * Hoist scalar products alpha*A[i,k] and tmp[i,k] out of the j-loop.
#   * Separate initialization/scaling from the matrix products.
# Scheduling directives below then:
#   * Parallelize the two matrix multiplications over i.
#   * Tile the j-dimension of both GEMMs to improve cache locality for B and C.

@proc
def kernel_2mm(
    ni: size,
    nj: size,
    nk: size,
    nl: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    tmp: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
    C: DATA_TYPE[nj, nl] @ DRAM,
    D: DATA_TYPE[ni, nl] @ DRAM,
):
    # Basic sanity: problem sizes must be positive
    assert ni > 0
    assert nj > 0
    assert nk > 0
    assert nl > 0

    # 1) Initialize tmp to zero.
    #    This makes the subsequent GEMM a pure accumulation.
    for i in seq(0, ni):
        for j in seq(0, nj):
            tmp[i, j] = 0.0

    # 2) First matrix multiplication:
    #       tmp = alpha * A * B
    #
    #    Loop order i-k-j gives:
    #      * j as the innermost loop
    #      * B[k, j] accessed with unit stride along j
    #      * A[i, k] reused across the j-loop via a_ik
    for i in seq(0, ni):
        for k in seq(0, nk):
            a_ik: DATA_TYPE
            a_ik = alpha * A[i, k]
            for j in seq(0, nj):
                tmp[i, j] += a_ik * B[k, j]

    # 3) Scale D by beta once, instead of inside the reduction.
    for i in seq(0, ni):
        for j in seq(0, nl):
            D[i, j] = beta * D[i, j]

    # 4) Second matrix multiplication:
    #       D += tmp * C
    #
    #    Again we use i-k-j ordering so that:
    #      * j is innermost
    #      * C[k, j] is accessed with unit stride
    #      * tmp[i, k] is reused across the j-loop via t_ik
    for i in seq(0, ni):
        for k in seq(0, nj):
            t_ik: DATA_TYPE
            t_ik = tmp[i, k]
            for j in seq(0, nl):
                D[i, j] += t_ik * C[k, j]


# ----------------
# Scheduling phase
# ----------------

# Start from the object-code kernel.
p_opt = kernel_2mm

# Parallelize the two compute-heavy matrix multiplications over 'i'.
# There are four 'i' loops in the procedure:
#   [0] tmp initialization
#   [1] tmp = alpha * A * B
#   [2] D scaling
#   [3] D += tmp * C
i_loops = p_opt.find_loop("i", many=True)
p_opt = parallelize_loop(p_opt, i_loops[1])
p_opt = parallelize_loop(p_opt, i_loops[3])

# Tile the j-dimension of both GEMMs to improve cache locality for B and C
# and to create a small, unit-stride inner loop that the backend can
# efficiently vectorize. The tile size can be tuned for the target cache;
# 32 is a reasonable default for modern x86 with wide SIMD.
Tj = 32

j_loops = p_opt.find_loop("j", many=True)
# j_loops[1]: j-loop in tmp = alpha * A * B
# j_loops[3]: j-loop in D += tmp * C
p_opt = divide_loop(p_opt, j_loops[1], Tj, ["jo_tmp", "ji_tmp"], tail="guard")
p_opt = divide_loop(p_opt, j_loops[3], Tj, ["jo_D", "ji_D"], tail="guard")

