    nj: size,
    nk: size,
    nl: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    tmp: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
    C: DATA_TYPE[nj, nl] @ DRAM,
    D: DATA_TYPE[ni, nl] @ DRAM,
):
    # Compute D := alpha * A * B * C + beta * D

    # First matrix multiplication: tmp = alpha * A * B
    # Naive row-major triple loop; will be optimized by scheduling below.
    for i in seq(0, ni):
        for j in seq(0, nj):
            tmp[i, j] = 0.0
            for k in seq(0, nk):
                tmp[i, j] += alpha * A[i, k] * B[k, j]

    # Second matrix multiplication and accumulation:
    # D = beta * D + tmp * C
    for i in seq(0, ni):
        for j in seq(0, nl):
            D[i, j] = beta * D[i, j]
            for k in seq(0, nj):
                D[i, j] += tmp[i, k] * C[k, j]


# ---------------------------------------------------------------------------
# Scheduling / optimization
# ---------------------------------------------------------------------------
# We start from the straightforward kernel_2mm_base implementation above and
# apply loop transformations to improve memory access patterns:
#
# - In both GEMMs we:
#     * Separate the initialization (tmp zeroing / D scaling) from the
#       accumulation loops (using fission).
#     * Reorder the accumulation loops so that j is the innermost index.
#       Because arrays are row-major, this makes accesses to B[k, j],
#       C[k, j], tmp[i, j], and D[i, j] contiguous in memory, improving
#       cache utilization and enabling auto-vectorization by the C compiler.
#
# The final optimized procedure is exposed under the name `kernel_2mm`,
# which is what the C driver calls.

p = kernel_2mm_base

# --- Optimize the first GEMM: tmp = alpha * A * B -------------------------

# 1) Separate initialization of tmp from the accumulation. Initially we have:
#    for i:
#      for j:
#        tmp[i, j] = 0.0
#        for k:
#          tmp[i, j] += alpha * A[i, k] * B[k, j]
#
# After fission at the gap after `tmp[i, j] = 0.0`, we obtain:
#    for i:
#      for j:
#        tmp[i, j] = 0.0
#    for i:
#      for j:
#        for k:
#          tmp[i, j] += ...
tmp_zero = p.find("tmp[i, j] = 0.0")
p = fission(p, tmp_zero.after())

